"use client";
import "./glass-surface.css";
import "./glass-card.css";

/**
 * GlassCard: a panel to group content. Cards can sit inside cards.
 * title, text  optional heading and supporting line
 * level        1 (default) or 2 for a card inside another card
 * active       highlights the card with the brand colour
 * effect       "flat" | "glass" | "bubble"
 */
export function GlassCard({ title, text, level = 1, active = false, effect = "flat", className = "", children, ...rest }) {
  return (
    <div className={`gc ${className}`.trim()} data-level={level} data-effect={effect} data-active={active ? "" : undefined} {...rest}>
      {title && <h3 className="gc-title">{title}</h3>}
      {text && <p className="gc-text">{text}</p>}
      {children}
    </div>
  );
}

/**
 * GlassProgress
 * value, max   numbers; max defaults to 100
 * label        text on the left; the percentage shows on the right
 * accent       fill with the brand colour and a soft glow
 */
export function GlassProgress({ value = 0, max = 100, label, showValue = true, accent = false }) {
  const pct = Math.max(0, Math.min(100, (value / max) * 100));
  return (
    <div className="gpr" data-accent={accent ? "" : undefined}>
      {(label || showValue) && (
        <div className="gpr-head">
          <span>{label}</span>
          {showValue && <span>{Math.round(pct)}%</span>}
        </div>
      )}
      <div className="gpr-track" role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(pct)}>
        <div className="gpr-fill" style={{ "--gpr-value": pct }} />
      </div>
    </div>
  );
}

/* Card and progress bar. */
.gc {
  --gc-fill: #fff;
  --gc-backdrop: none;
  --gc-ring: rgb(var(--glass-shadow) / 0.1);
  --gc-rim-hi: transparent;
  --gc-rim-lo: transparent;
  --gc-radius: 24px;
  --gc-drop: 0 1px 2px rgb(var(--glass-shadow) / 0.05), 0 14px 30px -20px rgb(var(--glass-shadow) / 0.3);

  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
  padding: 22px;
  border-radius: var(--gc-radius);
  color: var(--glass-fg);
  background: var(--gc-fill);
  -webkit-backdrop-filter: var(--gc-backdrop);
  backdrop-filter: var(--gc-backdrop);
  box-shadow: 0 0 0 1px var(--gc-ring), var(--gc-drop);
}
/* Bevel: a light line just inside the outer edge */
.gc::after {
  content: "";
  position: absolute;
  inset: 1px;
  z-index: -1;
  padding: 0.5px;
  border-radius: calc(var(--gc-radius) - 1px);
  pointer-events: none;
  background: linear-gradient(135deg, var(--gc-rim-hi), var(--gc-rim-lo) 38%, var(--gc-rim-lo) 62%, var(--gc-rim-hi));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
}
.gc[data-effect="glass"],
.gc[data-effect="bubble"] {
  --gc-fill: linear-gradient(180deg, rgb(255 255 255 / 0.55), rgb(255 255 255 / 0.3));
  --gc-backdrop: blur(var(--glass-blur)) saturate(1.8) brightness(1.06);
  --gc-ring: rgb(var(--glass-shadow) / 0.07);
  --gc-rim-hi: rgb(255 255 255 / 1);
  --gc-rim-lo: rgb(255 255 255 / 0.3);
}
/* Level 2: a card inside a card */
.gc[data-level="2"] {
  --gc-fill: rgb(var(--glass-shadow) / 0.04);
  --gc-radius: 18px;
  --gc-drop: 0 0 0 0 transparent;
  padding: 18px;
}
/* Active: the edge takes the brand colour and light falls in from the top */
.gc[data-active] {
  background: linear-gradient(180deg, color-mix(in srgb, var(--glass-tint) 16%, transparent), transparent 45%), var(--gc-fill);
  box-shadow:
    0 0 0 1.5px var(--glass-tint),
    0 0 0 5px color-mix(in srgb, var(--glass-tint) 18%, transparent),
    var(--gc-drop);
}
.gc-title { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -0.01em; line-height: 1.2; }
.gc-text { margin: 0; font-size: 14px; opacity: 0.8; }

/* ---------- Progress ---------- */
.gpr { display: flex; flex-direction: column; gap: 8px; min-width: 0; color: var(--glass-fg); }
.gpr-head { display: flex; justify-content: space-between; gap: 12px; font-size: 14px; font-weight: 500; font-variant-numeric: tabular-nums; }
.gpr-track {
  --gpr-track: rgb(var(--glass-shadow) / 0.1);
  --gpr-fill: rgb(var(--glass-shadow) / 0.6);
  --gpr-edge: rgb(255 255 255 / 0.4);
  height: 12px;
  border-radius: 999px;
  background: var(--gpr-track);
}
.gpr-fill {
  width: calc(var(--gpr-value) * 1%);
  min-width: 12px;
  height: 100%;
  border-radius: inherit;
  background: var(--gpr-fill);
  box-shadow: inset 0 0 0 1.5px var(--gpr-edge);
  transition: width 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.gpr[data-accent] .gpr-fill {
  --gpr-fill: var(--glass-tint);
  --gpr-edge: color-mix(in srgb, var(--glass-tint) 55%, #fff);
  box-shadow: inset 0 0 0 1.5px var(--gpr-edge), 0 0 14px color-mix(in srgb, var(--glass-tint) 45%, transparent);
}
@media (prefers-reduced-motion: reduce) { .gpr-fill { transition: none; } }

/* Mist over a dark picture (data-glass-on="dark"): a clear pane with white text */
[data-glass-tint="frost"] [data-glass-on="dark"] .gc[data-effect="glass"],
[data-glass-tint="frost"] [data-glass-on="dark"] .gc[data-effect="bubble"] {
  --gc-fill: linear-gradient(180deg, rgb(255 255 255 / 0.16), rgb(255 255 255 / 0.05));
  --glass-fg: #fff;
  --glass-shadow: 255 255 255;
  color: #fff;
}
